        "month": "ספטמבר",
        "updates": "11.5.25 - איתי נקלט בכיתה ט/2. מרבה להסתובב בחוץ, אינו פנוי ללמידה. שואל שאלות רבות על עישון סמים ועישון בכלל בשטח ביה\"ס, גבולות מותר ואסור בביה\"ס, מרבה לשתף את אנשי הצוות החינוכי בקורות חייו. \n23.5.25 - איתי עובר תקיפה מינית קשה מאוד בעיר חיפה. מצורף בתיק דו\"ח אירוע חריג. \n28.5.25 - איתי מגיע לביה\"ס ואינו פנוי ללמידה, אינו נכנס לשיעורים. בשיחה בחדרי, איתי מספר על החקירה שעבר אתמול במשטרת חיפה, צפייה בסרטוני האירוע והתגובות הקשות שעבר כתוצאה מכך. ניכר כי הוא נהנה לזעזע את השומע. אני חוזרת ומדגישה בפניו לא לשתף תלמידים באירוע. איתי מבקש להיפגש עם פסיכולוג ביה\"ס, אני מסבירה לו שהדבר אינו אפשרי וכי עליו לקבל טיפול מותאם במסגרת הקהילה. \n\nשיחה טלפונית עם אמא של איתי. היו בפגישת אינטק בלשכת הרווחה בבנימין עם עו\"ס נפגעי עבירה בשם מוריה. לדברי האם, מוריה אמרה שהיא לא מבינה למה ביה\"ס הרחיק את איתי. תדבר עם שירה ושירה תעדכן אותנו. איתי רוצה לחזור לביה\"ס. יהיה בטיפול חד-שבועי אצל מוריה עד שיקבל מקום במרכז מיטל. כרגע נעשתה הפניה למרכז מיטל. לא רוצה שאיתי ירגיש שהוא \"נענש\" ומבקשת שיחזור לחיים רציפים. אחת לחודש מעקב במחלקה הפסיכיאטרית ב\"איתנים\".\n\nשיחה טלפונית עם מוריה (עו\"ס נפגעי עבירה) המטפלת באיתי.  \n\n9.6.25 - בערב: שיחה טלפונית עם אמא של איתי - מיטל מסבירה לה ש\"לנו אין את הכלים הטיפוליים להתמודד עם נפגעי תקיפה מינית. כשאיתי מוצף או בחרדה - אנחנו לא יודעים לטפל בזה. הכלי היחידי שנשאר לנו הוא הכלי החינוכי. נחתום על הסכם עם איתי שלפיו הוא לא יכול לדבר עם תלמידים על מה שהוא עבר\".\nלגבי מחלות מין שהוא טען שייתכן שנדבק בהן, האם אומרת ש\"הסיכוי הוא אפסי\". מיטל: \"אנחנו צריכים שאיתי יבין שכל דבר שהוא יגיד עכשיו יכול להצית אש ולכן הוא צריך להיות מאוד זהיר במה שהוא אומר\". האם טוענת כי \"איתי נמצא כרגע במקום שהוא מדחיק את מה שקרה לו, הוא לא רוצה עכשיו לדבר על המקרה. הוא כבר לא מוצף, הוא הרבה יותר רגוע\".\n\n13.7.25 - שיחת עדכון טלפונית עם איתי, בחופש הגדול. מספר שהוא משועמם מאוד, מסרב לנסות לחפש עבודה ומתלונן על היעדר חברים מהיישוב. נמצא בקשר רוב שעות היום עם חברים מאפליקציות שונות, מכל רחבי הארץ. יוצא עם האבא למסעדות פעמיים בשבוע. ח שד כי מחלת הסרטן חזרה אצל האם - ממתינים לתוצאות הביופסיה, להיות בקשר! הבקשה שלו לפנימייה טיפולית נדחתה, כרגע לדבריו ממשיך בביה\"ס. מבקש להיות עם גפן וליאל בכיתה בשנה הבאה.",
