      "familyCircle": "ציון וסגול גרושים + 3 \nלגוני אח אילי בן 17, אחות גיא בת 19\nגוני היה בן שנה ושמונה חודשים כשהוריו התגרשו\n\nמשיחה עם האם היא שמחה שגוני עוזב את ביה\"ס הוא חווה התקפי חרדה במיוחד בימי זיכרון ושם לא היתה הכלה.\nבילה הרבה מאוד בחוץ בביה\"ס הקודם, לא היו שעורי ספורט.\nילד שזקוק לפעילות ולא יכול לשבת.\nחושש קצת מילד נחמן נתן ממושב אדרת, אברר זאת, נתן היה אצלנו שנה קודם.\nזקוק לתפקיד בכיתה ועיסוקים. \n\nכל פעם שיש הסטריה עם המצב המלחמתי הוא מרגיש מוצף ואפשר להרגיע אותו. \nהאם גידלה אותו כל השנים ובשנים האחרונות הם גרים עם האב בעיקר במושב אדרת והאם מתגוררת במושב צפרירים 5 דקות .\nלאם יש בן זוג שאנחנו גרים בקרוון בשטח ולו יש 3 ילדים. יש עוד חדר נוסף או אוהלים. סגול ספרית כלבים ורפואה משלימה בבעלי חיים, עסק משלי עצמאית. \n\nגוני אוהב בעלי חיים, ממליצה להכניס לקבוצה של בעלי חיים ונבחרת כדורגל.\nרוצה עיצוב שיער. הוא עדין משחק בשכונה וגם באופן מקצועי יהיה השנה.\n\nכל היסודי היה מצויין רק סביב ז ח התחילו בעיות חברתיות כי היו קבוצות שלא רצו לשתף אותו.",
