      "prevSchool": "דרור צור הדסה\nרגילה",
      "diagnosis": "דוח פסיכיאטרי מתאריך 21.5.24\nמאז גירושי הוריו מתואר כילד שסבל מחרת נטישה והתקפי זעם, קשר טוב עם האב. מגיל שלוש ישן במיטת הוריו.\nעד מספר חודשים לפני ה 7.10 היה נוהג לציין את ימי הזכרון כדי להתכונן לצפירה, כנראה שהצפירה מהווה איום.\nמצוק איתן סובל מחרדות וכאבי בטן, פחד ללכת לביה\"ס בגלל הפחד שלא ידע איפה הממד. גם כשהיה הולך היה מבקש מאביו לאסוף אותו במהלך היום. \nלא נשאר בבית לבד.\nמתואר כילד שאינו מסוגל לשבת, עד עתה לא נעשה אבחון קשב וריכוז ולא מטופל, לא מצליח בלמידה ולא ניגש למבחנים. הוא מתאר את חוסר השקט שלו והתזזתיות, החרדות מאזעקות וחוסר יכולת לישון בשל כך.\nחברתי מצבו טוב, יש לו חברים והוא שומר על קשר עין הופעה נקייה.\nהמלצות להורים:\nסל סיוע, לשם כך צריך אבחון פסיכודידקטי\nהמשך טיפול רגשי לגוני בשל חרדה\nבדיקת קשב וריכוז וטיפול בהתאם\nהדרכת הורים\n\nמאובחן בקשב וריכוז לא לוקח רטלין בשל החרדות שלו.\nהאם מטפלת בו בשמנים הטריים.",
