        "month": "ספטמבר",
        "updates": "שיחה עם צופיה לפני הפניה לקידום נוער.\nצופיה מבקשת לסיים עם בגרות באנגלית כבר בכיתה י', יש לבדוק היתכנות. שואפת ל- 5 יח\"ל במתמטיקה ובמחשבים, כמו אחותה. מספרת על קושי בהתמודדות עם השפה העברית. מביעה רצון לפגוש את הילה מקידום נוער.  \n22.11.24 - הפניה לקידום נוער, במסגרת בית הספר. באישור האם. \nצופיה מבקשת לסיים את המפגשים עם הילה, במסגרת קידום נוער בביה\"ס. אמא של צופיה מעדכנת בשיחה טלפונית כי צופיה לא מרגישה בנוח עם השאלות האישיות של המטפלת, ומבקשת לא להמשיך את הליווי הרגשי. עדכון ליסכה.\nשיחה משמעותית עם צופיה במהלך יום המעשים הטובים\" ביער לטרון. צופיה מסוגרת בעולם שלה, עם אוזניות או ספר, משדרת ריחוק וניכור כלפי בנות הכיתה. לדבריה, יש לה הרבה חברות מחוץ לביה\"ס ולא חסרה לה חברת בני גילה. הקהילה סובבת אותה והיא פעילה בהרבה מיזמים בשעות אחה\"צ. שוקדת על כתיבת ספר פנטזיה ובאופן כללי מבהירה כי הגיעה.\nלאורט כדי להוציא תעודת בגרות ולחזק את השפה העברית.  \n\nבמפגש הראשון התרשמתי לטובה, הסירה את האזניות משנה קודם ושיתפה שהיא מנגנת בצ'לו ורוצה להתמקצע. גם שרה עם הלהקה. נראה שההצטרפות של חנה טובה לה ממש. הן הסתובבו בהפסקות בחוץ ודיברו עם הצוות.",
