        "updates": "תאיר נפגשת בקביעות עם מתיאס. \nמבקשת להגיע רק 4 ימים בשבוע לביה\"ס בטענה שקשה לה להגיע בכל יום. איום מרומז שאם לא תקבל יום בבית תגיע למצב של נשירה. \n30.11.25 - אמא של תאיר מתקשרת למיטל ומבקשת שתאיר תדע שהיא אמא מעורבת, שהיא מתעניינת בה ושהיא בתמונה. מיטל מבהירה לה שביה\"ס חייב להישאר מקום מוגן ובטוח עבור תאיר, מקום שהוא \"שלה\" ושהיא תמשיך להגיע. מיטל מספרת לה על התקף החרדה שתאיר קיבלה כששמעה בתחילת השנה שהאם שוחחה עם הצוות. האם אומרת שהניכור ההורי אינו מיטיב עם תאיר, אך מיטל מבהירה לה שאין זה מתפקידו של ביה\"ס לשמש גשר בסיפור המשפחתי המורכב וכי יש צורך בגישור דרך הרווחה בלבד. האם מבקשת פגישה עם מיטל, מיטל מבקשת לצרף את העו\"סית לענייני משפחה (אביטל). פגישה תקבע לאחר חנוכה.\nאמא של אליה כהן (אורלי), המכירה את אמא של תאיר,  מתקשרת למיטל כעבור כמה דקות כדי ללמד זכות על האם לאחר שלדבריה האם חשה שמיטל שוחחה איתה בקרירות.",
