        "updates": "7.1.26 - תאיר אומרת למתיאס שאין לה כוונות להגיע לביה\"ס, רק ל   פגישות איתו. משמיעה דברים דומים בשיחה אישית עם אושר. סבורה שהיא לא שייכת לכאן ורוצה לעבור למקום שמתאים לה יותר.\n8.1.26 - שיחה טלפונית של מיטל עם האבא דני, מאשש את הדברים של תאיר לגבי רצונה למצוא מסגרת חדשה. יסכה מעדכנת את הקב\"סית.\nווטסאפ שלי לתאיר לעדכן אותה לגבי הפגישה עם האם והרווחה ביום שני הקרוב בביה\"ס. \n\n12.1.26 - פגישה עם לימור (אמא של תאיר) + אביטל - עו\"סית משפחה מגוש עציון. נוכחים: מיטל, מתיאס, יסכה ואני. \nמיטל מעדכנת שתאיר הפסיקה להגיע לביה\"ס והיא מצהירה שאין לה כוונות לחזור, למעט לטיפול אצל מתיאס. תאיר \"מפילה\" את העניין על הילדים בביה\"ס וטוענת כי אינם מתאימים לה. \nמתיאס: \"תאיר התחילה להביע התנגדות לאוכ' הילדים בביה\"ס ולמרחק הרב מהבית. התגמשנו מאוד כדי שתאיר תגיע ותשתף פעולה עם מה שיש לביה\"ס להציע, אבל לא נראה שהיא מתכוונת לשנות את דעתה\". \nמיטל: \"תאיר מבקשת וודאות והחלטנו לעבוד מולה בשקיפות מלאה כי התחושה הייתה שהיא רוצה שליטה. היא מתייחסת לא יפה לחברים בכיתה, יחס מזלזל ונמצאת בתחושה שזה לא המקום שלה.\nלימור האם: \"תאיר לא סובלת מחרדה חברתית. היא מחליטה על הכל לבד ושולטת בהכל. יש בעיית אמון עמוקה במבוגרים\".\nסיכום: הרווחה בגוש עציון תתערב במקרה, כולל אפשרות למעורבות של עו\"ס חוק נוער. הרווחה תכנס ועדת תכנון טיפול. \n\n13.1.26 - שיחה טלפונית שלי לאבא דני, לעדכון. מעדכנת אותו בדבר הפגישה אתמול ועל כך שתתקיים ועדת תכנון טיפול שתכונס ע\"י הרווחה. דני: \"תודה, מעולה\".",
