        "updates": "4.11.25 - שיחת אזהרה ליניב בטרם מעבר לכיתה י\"א2. נוכחים: מיטל, יעקב, יסכה, רווית, אני. יניב מביע התנגדות לעבור לכיתה י\"א2 בטענה שהוא רוצה לעשות בגרות, אך באותה נשימה אומר כי הוא לא רוצה ללמוד ואין לו כוח ללימודים בכלל. מסרב לקחת ריטלין, מפגין אדישות וזלזול.\nמבקש ממיטל לאפשר לו שבוע ניסיון בטרם תתקבל ההחלטה בעניינו. \nיניב מסכם עם מיטל שבשבוע הקרוב ייכנס לשיעורים כיתה, יגיע בזמן לביה\"ס, לא יפריע למהלך השיעור ויתנהג כתלמיד. \n6.11.25 - יניב מביא חבר מנתניה לביה\"ס, נותן לו ללבוש חולצת שמיניסטים ונותן  ל לשהות איתו במשך שלוש שעות במרחבי ביה\"ס. \n10.11.25 - יניב מלהיט את הרוחות בסיטואציה שבה תלמיד כיתה י' מקלל את המורה גיא בהפסקה. \n18.11.25 - ועדה בית-ספרית שנייה מתכנסת בעניינו של יניב (בנוכחות מיטל, רוית, יעקב, יסכה ואני). החלטת הוועדה: יניב עובר לכיתה י\"א2 ואם ירצה ויוכיח את רצינותו בלימודים יוכל לשוב לכיתה י\"א1 ולגשת לבגרות. יניב מגיב בכעס ונדמה כי אינו מבין את הפער בין הצהרותיו לפיהן הוא רוצה תעודת בגרות מלאה, לבין מעשיו שאינם מעידים על כך כלל. פרוטוקול הוועדה מצ\"ב בתיק.\n(\"אין לי בשביל מה לבוא לכאן אם אתם קובעים שאני עובר ל-י\"א1\"). יעקב מעדכן את האב. \n22.11.25 - יניב מעורב בתקרית אלימה חריגה המתועדת במצלמות ביה\"ס. מכה חסר ישע. דו\"ח אירוע חריג מוגש (מצ\"ב בתיק). השעיה לשבוע.",
