        "updates": "24.11.25 - בעקבות המכות שליאם קיבל בחצר ביה\"ס, מיניב וממיכאל, שיחה טלפונית עם האם. מספרת שליאם היה נפוח מבכי כשחזר מביה\"ס. זה דברים שאתם לא צריכים לעבור עליהם בשתיקה. מספרת שליאם אומר שהוא מפחד מהילדים האלה, שהם יוציאו עליו סכין. לדבריה, גם הילדים שראו את האירוע ולא התערבו היו צריכים להיות מושעים. \n25.11.25 - שיחה עם האם לקבלת הסכמה להפניה לקידום נוער. מספרת שהתקשרה גם למנהלת ביה\"ס בעקבות אירוע התקיפה שליאם עבר וכי המשפחה אינה מצליחה להירגע מהמקרה הקשה. לדבריה, ליאם מפחד מהרגע שבו התוקפים יחזרו לביה\"ס ואף אמר לה שהוא מפחד שהם \"ישלפו עליי סכין\". אומרת כי שקלה פנייה למשטרה ודורשת מביה\"ס למצות את הטיפול בפרשה.  \nשמחה מאוד על הפניה לגבי קידום נוער. ליאם לא נמצא כרגע בשום טיפול רגשי לאחר שהפסיק טיפול עם פסיכולוג כשהרגיש שאין התקדמות. מבקשת שהשיח עם קידום נוער יהיה פחות טיפולי ויותר חברי-משחקי. \n30.11.25 - אבא של ליאם מגיע לביה\"ס כדי לעמוד מקרוב על הטיפול בילדים שפגעו לטענתו בבן שלו. מיטל מסבירה לו שאין כניסת הורים למטרות אלה והוא יוצא משטח ביה\"ס. שיחה עם שרית המפקחת - להיות במקום האמפטי כלפי ההורים אבל גם לשקף להם שאנחנו מחנכים וחינוך זה תהליך. \nשיחה עם ליאם בחדר של מיטל: ליאם אומר שהוא אינו מרגיש חוסר מוגנות בביה\"ס. מיטל מדגישה בפניו את אנשי הצוות החינוכי העומדים לרשותו בפנייה בכל עניין, מבקשת לדעת כשיש הצקה אפילו מינורית, מסבירה לליאם כי ייתכן שהפוגעים יחזרו בימים הקרובים לביה\"ס אחרי שהעניין בהם טופל, אך תחושת המוגנות שלו לא אמורה להיפגע.\nליאם מביע רצון לעבור לכיתה י\"א3, של גיא.   \nשיחה שלי עם אמא של ליאם: הבעת אמפטיה כלפי הדאגה שלהם לליאם בביה\"ס, שיקוף הדברים שאמר ליאם למיטל על תחושת המוגנות שהוא חש בביה\"ס, הסבר על הטיפול בנערים הפוגעים. אמא של ליאם בהבנה ומקבלת את הדברים.",
