        "updates": "2.12.25 - שיחה טלפונית שלי עם ההורים של ליאורה: מספרים שליאורה עוברת משבר לא פשוט. מתארים שמירת היריון ולחץ גדול, לידה בעייתית עם חוסר בחמצן, ילדה שקטה וקטנה שלא דיברה עם אף אחד, אפילו לא עם הגננת. בעיות תקשורת, גן שילוב, ילדה \"שקופה\". בכיתות ג'-ד' חוותה התעללות קשה מצד חברות לכיתה ולא סיפרה דבר. בקורונה הייתה בודדה מאוד וחוותה קושי גדול. עברה לביה\"ס טל-רמות וגם שם עברה התעללות רגשית ומילולית. בכיתה ט' עברה לכיתה מקדמת בצביה ירושלים  מבקשת עזרה בשותפות עם ביה\"ס.\nישיבה פדגוגית: קשיים חברתיים, תחושת חוסר מסוגלות. לייצר שפה משותפת עם המורים האחרים - לומר לה \"את יכולה\"; לייצר לה עבודה בזוגות עם חבר'ה רלוונטיים. מתחילה טיפול אצל שרה. פרלה תתקשר להזמין אותה למספרה בימי חמישי.",
