        "updates": "29.1.26 - 11:05 מאי מטפלת רגשית פונה אליי עם חובת דיווח לגבי אילה: אילה שיתפה שהותקפה באלימות לפני שבועיים ע\"י בן הזוג שלה. היא לא מעוניינת להתלונן במשטרה, לא רוצה לשתף בעניין את ההורים (שנמצאים עם האחות שלה בחדר הלידה). בן הזוג האלים משתמש באיומים ובמניפולציות (מאיים להתאבד למשל) כדי שאילה לא תעזוב אותו. מאי תשלח אליי דיווח.  \n11:20 התייעצות עם יעל, מדריכת יועצות: מציעה להתייעץ עם עו\"ס חוק נוער.\n11:30 התייעצות טלפונית עם נועם, עו\"ס חוק נוער אזור דרום: אם לא מדובר בפוגע שהוא בן משפחה / אחראי עליה שפוגע בקטינה - אין דיווח למשטרה. אין טעם בשליחת דיווח מטעם ביה\"ס לפקידת סעד בעניין. פעולות שיש לעשות:\nליידע את ההורים של אילה \nלשוחח עם אילה (את סובלת ולא מגיע לך לסבול, את בסכנה) ולנסות לשכנע אותה להגיש תלונה במשטרה / להיפרד מיד מהחבר האלים\n  להציע לאילה טיפול במיט\"ל לנפגעות אלימות ותקיפה מינית\n\n12:30 - עדכון מיטל המנהלת. סוכם שאני איידע את ההורים\n12:40 - שיחה עם מאי מטפלת רגשית, תעדכן את אילה בעניין חובת הדיווח אחרי הבגרות. מבקשת ממני להמתין עם הטלפון להורים עד אחרי השעה 17:00. \n18:00 - מאי המטפלת הרגשית מדברת עם אילה ומעדכנת אותי שיידעה אותה שביה\"ס יודע ומתכוון לעדכן את ההורים\n19:30 - שיחה טלפונית מיטל + אני עם אמא של אילה. לדבריה, ידעה שאילה נפרדה מבן הזוג לפני שבוע, אך לא ידעה למה. תשוחח עם אילה. \nדו\"ח אירוע חריג נשלח. מיטל עודכנה.",
